fn parity_decimal128_bid_copy(failures: &mut Vec<String>) -> usize {
    let mut count = 0usize;
    for &v0 in CORPUS_128 {
        let a = Decimal128::from_le_bytes(v0);
        // Rust's Copy (implicit memberwise bit copy on a #[repr(transparent)]
        // single-field struct) is the language-level identity the Go .Copy
        // port entrypoint implements at runtime; comparing the two proves the
        // port's Copy is bit-identity, matching Rust's Copy trait semantics.
        let b_copy = a;
        let pr = bid754::generated::bid128_noncomp::bid128_copy(to_port128(v0));
        if b_copy.to_le_bytes() != from_port128(pr) {
            failures.push(format!("public parity Decimal128BID.Copy: operand {:x?}: result mismatch public={:?} port={:?}", v0, b_copy.to_le_bytes(), from_port128(pr)));
        }
        count += 1;
    }
    count
}

