fn parity_decimal128_bid_div_with_mode(failures: &mut Vec<String>) -> usize {
    let mut count = 0usize;
    for &(i0, i1) in PAIRS_128 {
        let v0 = CORPUS_128[i0];
        let v1 = CORPUS_128[i1];
        for &(mode, port_mode) in PARITY_MODES {
            let (pv, pf) = Decimal128::from_le_bytes(v0).div_with_mode(Decimal128::from_le_bytes(v1), mode);
            let (pr, praw) = bid754::generated::bid128_div::bid128_div(to_port128(v0), to_port128(v1), port_mode);
            if pv.to_le_bytes() != from_port128(pr) {
                failures.push(format!("public parity Decimal128BID.DivWithMode: operands {:x?},{:x?} mode {:?}: result mismatch public={:?} port={:?}", v0, v1, mode, pv.to_le_bytes(), from_port128(pr)));
            }
            if pf.bits() != map_port_flags(praw) {
                failures.push(format!("public parity Decimal128BID.DivWithMode: operands {:x?},{:x?} mode {:?}: flag mismatch public={:#x} port={:#x}", v0, v1, mode, pf.bits(), map_port_flags(praw)));
            }
            count += 1;
        }
    }
    let disc_pairs: &[([u8; 16], [u8; 16])] = &[
        ([0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x40, 0x30], [0x03, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x40, 0x30]),
        ([0x02, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x40, 0x30], [0x03, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x40, 0x30]),
        ([0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x40, 0x30], [0x07, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x40, 0x30]),
        ([0x05, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x40, 0x30], [0x07, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x40, 0x30]),
    ];
    for &(da, db) in disc_pairs {
        let mut mode_seen = [[0u8; 16]; 5];
        for (mi, &(mode, port_mode)) in PARITY_MODES.iter().enumerate() {
            let (pv, pf) = Decimal128::from_le_bytes(da).div_with_mode(Decimal128::from_le_bytes(db), mode);
            let (pr, praw) = bid754::generated::bid128_div::bid128_div(to_port128(da), to_port128(db), port_mode);
            if pv.to_le_bytes() != from_port128(pr) {
                failures.push(format!("public parity Decimal128BID.DivWithMode: discriminant operands {:x?},{:x?} mode {:?}: result mismatch public={:?} port={:?}", da, db, mode, pv.to_le_bytes(), from_port128(pr)));
            }
            if pf.bits() != map_port_flags(praw) {
                failures.push(format!("public parity Decimal128BID.DivWithMode: discriminant operands {:x?},{:x?} mode {:?}: flag mismatch public={:#x} port={:#x}", da, db, mode, pf.bits(), map_port_flags(praw)));
            }
            mode_seen[mi] = pv.to_le_bytes();
            count += 1;
        }
        if mode_seen.iter().all(|s| *s == mode_seen[0]) {
            failures.push(format!("public parity Decimal128BID.DivWithMode: discriminant operands {:x?},{:x?}: every rounding mode produced the same result; the mode-discriminant corpus entry no longer discriminates", da, db));
        }
    }
    count
}

