fn parity_decimal32_bid_copy(failures: &mut Vec<String>) -> usize {
    let mut count = 0usize;
    for &v0 in CORPUS_32 {
        let a = Decimal32::from_bits(v0);
        // Rust's Copy (implicit memberwise bit copy on a #[repr(transparent)]
        // single-field struct) is the language-level identity the Go .Copy
        // port entrypoint implements at runtime; comparing the two proves the
        // port's Copy is bit-identity, matching Rust's Copy trait semantics.
        let b_copy = a;
        let pr = bid754::generated::bid32_noncomp::bid32_copy(v0);
        if b_copy.to_bits() != pr {
            failures.push(format!("public parity Decimal32BID.Copy: operand {:#x}: result mismatch public={:#x} port={:#x}", v0, b_copy.to_bits(), pr));
        }
        count += 1;
    }
    count
}

