fn parity_decimal32_bid_div_with_mode(failures: &mut Vec<String>) -> usize {
    let mut count = 0usize;
    for &(i0, i1) in PAIRS_32 {
        let v0 = CORPUS_32[i0];
        let v1 = CORPUS_32[i1];
        for &(mode, port_mode) in PARITY_MODES {
            let (pv, pf) = Decimal32::from_bits(v0).div_with_mode(Decimal32::from_bits(v1), mode);
            let (pr, praw) = bid754::generated::bid32_status::bid32_div_with_flags(v0, v1, port_mode);
            if pv.to_bits() != pr {
                failures.push(format!("public parity Decimal32BID.DivWithMode: operands {:#x},{:#x} mode {:?}: result mismatch public={:#x} port={:#x}", v0, v1, mode, pv.to_bits(), pr));
            }
            if pf.bits() != map_port_flags(praw) {
                failures.push(format!("public parity Decimal32BID.DivWithMode: operands {:#x},{:#x} mode {:?}: flag mismatch public={:#x} port={:#x}", v0, v1, mode, pf.bits(), map_port_flags(praw)));
            }
            count += 1;
        }
    }
    let disc_pairs: &[(u32, u32)] = &[
        (0x32800001, 0x32800003),
        (0x32800002, 0x32800003),
        (0x32800001, 0x32800007),
        (0x32800005, 0x32800007),
    ];
    for &(da, db) in disc_pairs {
        let mut mode_seen = [0u32; 5];
        for (mi, &(mode, port_mode)) in PARITY_MODES.iter().enumerate() {
            let (pv, pf) = Decimal32::from_bits(da).div_with_mode(Decimal32::from_bits(db), mode);
            let (pr, praw) = bid754::generated::bid32_status::bid32_div_with_flags(da, db, port_mode);
            if pv.to_bits() != pr {
                failures.push(format!("public parity Decimal32BID.DivWithMode: discriminant operands {:#x},{:#x} mode {:?}: result mismatch public={:#x} port={:#x}", da, db, mode, pv.to_bits(), pr));
            }
            if pf.bits() != map_port_flags(praw) {
                failures.push(format!("public parity Decimal32BID.DivWithMode: discriminant operands {:#x},{:#x} mode {:?}: flag mismatch public={:#x} port={:#x}", da, db, mode, pf.bits(), map_port_flags(praw)));
            }
            mode_seen[mi] = pv.to_bits();
            count += 1;
        }
        if mode_seen.iter().all(|s| *s == mode_seen[0]) {
            failures.push(format!("public parity Decimal32BID.DivWithMode: discriminant operands {:#x},{:#x}: every rounding mode produced the same result; the mode-discriminant corpus entry no longer discriminates", da, db));
        }
    }
    count
}

