fn parity_decimal32_bid_string(failures: &mut Vec<String>) -> usize {
    let mut count = 0usize;
    for &v0 in CORPUS_32 {
        // NaN entries take the hand-built display branch (which cannot be
        // compared against a raw port to_string call), so they are skipped
        // without counting, matching the Go leg's vm_string shape. Their
        // payload/sign display + round-trip is covered for every width by
        // generated_public_api_nan_roundtrip_<w> below (NOT by the
        // Decimal64-only smoke test).
        if bid754::generated::bid32_exports::bid32_is_na_n(v0) {
            continue;
        }
        let pv = Decimal32::from_bits(v0).to_string();
        let pr = bid754::generated::bid32_exports::bid32_to_string(v0);
        if pv != pr {
            failures.push(format!("public parity Decimal32BID.String: operand {:#x}: result mismatch public={:?} port={:?}", v0, pv, pr));
        }
        count += 1;
    }
    count
}

