fn parity_decimal64_bid_quantize_with_mode(failures: &mut Vec<String>) -> usize {
    let mut count = 0usize;
    for &(i0, i1) in PAIRS_64 {
        let v0 = CORPUS_64[i0];
        let v1 = CORPUS_64[i1];
        for &(mode, port_mode) in PARITY_MODES {
            let (pv, pf) = Decimal64::from_bits(v0).quantize_with_mode(Decimal64::from_bits(v1), mode);
            let (pr, praw) = bid754::generated::quantize64::bid64_quantize(v0, v1, port_mode);
            if pv.to_bits() != pr {
                failures.push(format!("public parity Decimal64BID.QuantizeWithMode: operands {:#x},{:#x} mode {:?}: result mismatch public={:#x} port={:#x}", v0, v1, mode, pv.to_bits(), pr));
            }
            if pf.bits() != map_port_flags(praw) {
                failures.push(format!("public parity Decimal64BID.QuantizeWithMode: operands {:#x},{:#x} mode {:?}: flag mismatch public={:#x} port={:#x}", v0, v1, mode, pf.bits(), map_port_flags(praw)));
            }
            count += 1;
        }
    }
    let disc_pairs: &[(u64, u64)] = &[
        (0x31a0000000000019, 0x31c0000000000001),
        (0x31a0000000000023, 0x31c0000000000001),
        (0xb1a0000000000019, 0x31c0000000000001),
        (0x31a000000000000f, 0x31c0000000000001),
    ];
    for &(da, db) in disc_pairs {
        let mut mode_seen = [0u64; 5];
        for (mi, &(mode, port_mode)) in PARITY_MODES.iter().enumerate() {
            let (pv, pf) = Decimal64::from_bits(da).quantize_with_mode(Decimal64::from_bits(db), mode);
            let (pr, praw) = bid754::generated::quantize64::bid64_quantize(da, db, port_mode);
            if pv.to_bits() != pr {
                failures.push(format!("public parity Decimal64BID.QuantizeWithMode: discriminant operands {:#x},{:#x} mode {:?}: result mismatch public={:#x} port={:#x}", da, db, mode, pv.to_bits(), pr));
            }
            if pf.bits() != map_port_flags(praw) {
                failures.push(format!("public parity Decimal64BID.QuantizeWithMode: discriminant operands {:#x},{:#x} mode {:?}: flag mismatch public={:#x} port={:#x}", da, db, mode, pf.bits(), map_port_flags(praw)));
            }
            mode_seen[mi] = pv.to_bits();
            count += 1;
        }
        if mode_seen.iter().all(|s| *s == mode_seen[0]) {
            failures.push(format!("public parity Decimal64BID.QuantizeWithMode: discriminant operands {:#x},{:#x}: every rounding mode produced the same result; the mode-discriminant corpus entry no longer discriminates", da, db));
        }
    }
    count
}

