fn parity_new_decimal128_from_int(failures: &mut Vec<String>) -> usize {
    let mut count = 0usize;
    for &x in INT_CORPUS_64 {
        let got = Decimal128::from_int(x);
        let text = x.to_string();
        let pr = bid754::generated::bid128_from_int::bid128_from_int64(x);
        let should_error = false;
        match got {
            Ok(pv) if should_error => {
                failures.push(format!("public parity NewDecimal128FromInt: operand {}: expected an exact-representation error, got {:?}", x, pv.to_le_bytes()));
            }
            Ok(pv) => {
                if pv.to_le_bytes() != from_port128(pr) {
                    failures.push(format!("public parity NewDecimal128FromInt: operand {}: result mismatch public={:?} port={:?}", x, pv.to_le_bytes(), from_port128(pr)));
                }
            }
            Err(e) if should_error => {
                let want_message = format!("integer {} is not exactly representable as Decimal128", x);
                if e.input() != text || e.target() != "Decimal128" || e.to_string() != want_message {
                    failures.push(format!("public parity NewDecimal128FromInt: operand {}: error mismatch input={:?} target={:?} message={:?}", x, e.input(), e.target(), e.to_string()));
                }
            }
            Err(e) => failures.push(format!("public parity NewDecimal128FromInt: operand {}: unexpected error {}", x, e)),
        }
        count += 1;
    }
    count
}

