fn parity_new_decimal32_from_int(failures: &mut Vec<String>) -> usize {
    let mut count = 0usize;
    for &x in INT_CORPUS_32 {
        let got = Decimal32::from_int(x);
        let text = x.to_string();
        let (pr, praw) = bid754::generated::bid32_from_int::bid32_from_int32(x, BIDGO_ROUND_NEAREST_EVEN);
        let should_error = map_port_flags(praw) & bid754::ExceptionFlags::INEXACT.bits() != 0;
        match got {
            Ok(pv) if should_error => {
                failures.push(format!("public parity NewDecimal32FromInt: operand {}: expected an exact-representation error, got {:#x}", x, pv.to_bits()));
            }
            Ok(pv) => {
                if pv.to_bits() != pr {
                    failures.push(format!("public parity NewDecimal32FromInt: operand {}: result mismatch public={:#x} port={:#x}", x, pv.to_bits(), pr));
                }
            }
            Err(e) if should_error => {
                let want_message = format!("integer {} is not exactly representable as Decimal32", x);
                if e.input() != text || e.target() != "Decimal32" || e.to_string() != want_message {
                    failures.push(format!("public parity NewDecimal32FromInt: operand {}: error mismatch input={:?} target={:?} message={:?}", x, e.input(), e.target(), e.to_string()));
                }
            }
            Err(e) => failures.push(format!("public parity NewDecimal32FromInt: operand {}: unexpected error {}", x, e)),
        }
        count += 1;
    }
    count
}

