/// One NaN-literal round-trip corpus entry: the input literal plus its
/// independently computed expected canonical display and sign/signaling
/// classification (see the Go-side parityNaNExpectation oracle).
struct NanCase {
    input: &'static str,
    display: &'static str,
    negative: bool,
    signaling: bool,
}

const NAN_CASES_64: &[NanCase] = &[
    NanCase { input: "NaN", display: "+NaN", negative: false, signaling: false },
    NanCase { input: "-NaN", display: "-NaN", negative: true, signaling: false },
    NanCase { input: "+NaN", display: "+NaN", negative: false, signaling: false },
    NanCase { input: "SNaN", display: "+SNaN", negative: false, signaling: true },
    NanCase { input: "-SNaN", display: "-SNaN", negative: true, signaling: true },
    NanCase { input: "+qnan", display: "+NaN", negative: false, signaling: false },
    NanCase { input: "snan", display: "+SNaN", negative: false, signaling: true },
    NanCase { input: "QNAN", display: "+NaN", negative: false, signaling: false },
    NanCase { input: "NaN42", display: "+NaN42", negative: false, signaling: false },
    NanCase { input: "-SNaN7", display: "-SNaN7", negative: true, signaling: true },
    NanCase { input: "qnan123", display: "+NaN123", negative: false, signaling: false },
    NanCase { input: "NaN999", display: "+NaN999", negative: false, signaling: false },
    NanCase { input: "SNaN000123", display: "+SNaN123", negative: false, signaling: true },
    NanCase { input: "NaN0", display: "+NaN", negative: false, signaling: false },
    NanCase { input: "-NaN0", display: "-NaN", negative: true, signaling: false },
    NanCase { input: " \tNaN55", display: "+NaN55", negative: false, signaling: false },
    NanCase { input: "NaN999999999999999", display: "+NaN999999999999999", negative: false, signaling: false },
    NanCase { input: "SNaN123456789012345", display: "+SNaN123456789012345", negative: false, signaling: true },
];

const EXPECTED_NAN_ROUNDTRIP_CASES_64: usize = 18;

#[test]
fn generated_public_api_nan_roundtrip_64() {
    let mut failures: Vec<String> = Vec::new();
    let mut count = 0usize;
    for nc in NAN_CASES_64 {
        let d = match Decimal64::parse(nc.input) {
            Ok(d) => d,
            Err(e) => {
                failures.push(format!("nan roundtrip 64: input {:?}: unexpected parse error {}", nc.input, e));
                continue;
            }
        };
        if !d.is_nan() {
            failures.push(format!("nan roundtrip 64: input {:?}: parse result is not a NaN", nc.input));
        }
        if d.is_signaling() != nc.signaling {
            failures.push(format!("nan roundtrip 64: input {:?}: signaling mismatch public={} expected={}", nc.input, d.is_signaling(), nc.signaling));
        }
        if d.is_sign_negative() != nc.negative {
            failures.push(format!("nan roundtrip 64: input {:?}: sign mismatch public={} expected={}", nc.input, d.is_sign_negative(), nc.negative));
        }
        let shown = d.to_string();
        if shown != nc.display {
            failures.push(format!("nan roundtrip 64: input {:?}: display mismatch public={:?} expected={:?}", nc.input, shown, nc.display));
        }
        // Oracle-independent fixed point: parse -> display -> parse must
        // reproduce the exact same bits. A payload/sign bit dropped or
        // altered by parse_decimal64_nan or format_decimal64_nan
        // makes the re-parse diverge here even if the display-string oracle
        // above happened to share the bug.
        match Decimal64::parse(&shown) {
            Ok(d2) => {
                if d.to_bits() != d2.to_bits() {
                    failures.push(format!("nan roundtrip 64: input {:?}: parse->display->parse bits diverged public={:#x} reparsed={:#x}", nc.input, d.to_bits(), d2.to_bits()));
                }
            }
            Err(e) => failures.push(format!("nan roundtrip 64: input {:?}: re-parse of display {:?} failed: {}", nc.input, shown, e)),
        }
        count += 1;
    }
    assert_eq!(count, EXPECTED_NAN_ROUNDTRIP_CASES_64, "nan roundtrip case count drifted");
    assert!(
        failures.is_empty(),
        "NaN payload/sign round-trip failures ({} total):\n{}",
        failures.len(),
        failures.join("\n")
    );
}
