#[test]
fn generated_public_api_const_parity_32() {
    let mut failures: Vec<String> = Vec::new();
    let mut count = 0usize;
    match Decimal32::parse("2.718282") {
        Ok(parsed) => {
            let const_bits = Decimal32::E.to_bits();
            let parsed_bits = parsed.to_bits();
            if const_bits != parsed_bits {
                failures.push(format!(
                    "const parity Decimal32::E: compile-time bits {:#x} != parse({:?}) bits {:#x}",
                    const_bits, "2.718282", parsed_bits
                ));
            }
        }
        Err(e) => failures.push(format!("const parity Decimal32::E: parse({:?}) failed: {}", "2.718282", e)),
    }
    count += 1;
    match Decimal32::parse("1") {
        Ok(parsed) => {
            let const_bits = Decimal32::ONE.to_bits();
            let parsed_bits = parsed.to_bits();
            if const_bits != parsed_bits {
                failures.push(format!(
                    "const parity Decimal32::ONE: compile-time bits {:#x} != parse({:?}) bits {:#x}",
                    const_bits, "1", parsed_bits
                ));
            }
        }
        Err(e) => failures.push(format!("const parity Decimal32::ONE: parse({:?}) failed: {}", "1", e)),
    }
    count += 1;
    match Decimal32::parse("3.141593") {
        Ok(parsed) => {
            let const_bits = Decimal32::PI.to_bits();
            let parsed_bits = parsed.to_bits();
            if const_bits != parsed_bits {
                failures.push(format!(
                    "const parity Decimal32::PI: compile-time bits {:#x} != parse({:?}) bits {:#x}",
                    const_bits, "3.141593", parsed_bits
                ));
            }
        }
        Err(e) => failures.push(format!("const parity Decimal32::PI: parse({:?}) failed: {}", "3.141593", e)),
    }
    count += 1;
    match Decimal32::parse("0") {
        Ok(parsed) => {
            let const_bits = Decimal32::ZERO.to_bits();
            let parsed_bits = parsed.to_bits();
            if const_bits != parsed_bits {
                failures.push(format!(
                    "const parity Decimal32::ZERO: compile-time bits {:#x} != parse({:?}) bits {:#x}",
                    const_bits, "0", parsed_bits
                ));
            }
        }
        Err(e) => failures.push(format!("const parity Decimal32::ZERO: parse({:?}) failed: {}", "0", e)),
    }
    count += 1;
    assert_eq!(count, EXPECTED_CONST_PARITY_CASES_32, "const parity case count drifted");
    assert!(
        failures.is_empty(),
        "const == parse(literal) parity failures ({} total):\n{}",
        failures.len(),
        failures.join("\n")
    );
}
